import { useMemo, useState, type PointerEvent } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from indexChart ----
type StockPoint = { date: Date; symbol: string; close: number };

/** [symbol, opening price, annual log drift, annual volatility] */
const STOCKS: [string, number, number, number][] = [
  ['AMZN', 257, 0.3, 0.26],
  ['NFLX', 13, 0.17, 0.24],
  ['MSFT', 27, 0.2, 0.21],
  ['GOOG', 361, 0.16, 0.22],
  ['AAPL', 19, 0.13, 0.24],
  ['ORCL', 34, 0.05, 0.2],
  ['IBM', 196, -0.06, 0.18]
];

const WEEKS = 313; // weekly closes, 2013-01-07 through 2018-12-31
const DT = 1 / 52;

/** mulberry32: a fixed seed keeps the chart identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = seededRandom(20260813);

const gaussian = () =>
  Math.sqrt(-2 * Math.log(1 - random())) * Math.cos(2 * Math.PI * random());

/** Geometric Brownian motion; the spread of drifts is what gives the index chart something to show. */
const techStocks: StockPoint[] = STOCKS.flatMap(([symbol, open, drift, vol]) => {
  let price = open;
  return Array.from({ length: WEEKS }, (_, week) => {
    price *= Math.exp((drift - (vol * vol) / 2) * DT + vol * Math.sqrt(DT) * gaussian());
    return { date: new Date(Date.UTC(2013, 0, 7 + week * 7)), symbol, close: price };
  });
});

const MARGIN = { top: 24, right: 48, bottom: 36, left: 52 };

/** Long-form closes; rows sharing a `symbol` become one series, each on the same dates. */
export type Data = { date: Date; symbol: string; close: number }[];

export default function IndexChart({
  data = techStocks,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 0.62);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const [refIndex, setRefIndex] = useState(0);

  const { dates, series } = useMemo(() => {
    const grouped = Array.from(d3.group(data, (d) => d.symbol));
    return {
      dates: grouped[0][1].map((d) => d.date),
      // Normalized to the first date only; re-indexing to any other date is a vertical
      // translation on a log scale, so the paths never have to be recomputed.
      series: grouped.map(([symbol, values]) => ({
        symbol,
        values: values.map((d) => d.close / values[0].close)
      }))
    };
  }, [data]);

  const x = useMemo(
    () =>
      d3
        .scaleUtc()
        .domain([dates[0], dates[dates.length - 1]])
        .range([0, innerWidth])
        .clamp(true),
    [dates, innerWidth]
  );

  // The scale spans the widest max/min ratio in the corpus, which is the most any
  // single series can travel once the reference date moves to its extreme.
  const y = useMemo(() => {
    const k =
      d3.max(series, (s) => (d3.max(s.values) ?? 1) / (d3.min(s.values) ?? 1)) ?? 1;
    return d3.scaleLog().domain([1 / k, k]).rangeRound([innerHeight, 0]);
  }, [series, innerHeight]);

  const paths = useMemo(() => {
    const line = d3
      .line<number>()
      .x((_, i) => x(dates[i]))
      .y((v) => y(v));
    return series.map((s) => ({
      symbol: s.symbol,
      d: line(s.values) ?? '',
      values: s.values,
      last: s.values[s.values.length - 1]
    }));
  }, [series, dates, x, y]);

  const color = useMemo(
    () => d3.scaleOrdinal(series.map((s) => s.symbol), d3.schemeObservable10),
    [series]
  );

  const xTicks: Tick[] = useMemo(
    () =>
      x.ticks(Math.max(2, Math.round(innerWidth / 90))).map((v) => ({
        value: d3.utcFormat('%Y')(v),
        offset: x(v)
      })),
    [x, innerWidth]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(6).map((v) => ({ value: `${d3.format('.2~f')(v)}×`, offset: y(v) })),
    [y]
  );

  function handlePointerMove(event: PointerEvent<SVGSVGElement>) {
    const [mx] = d3.pointer(event, event.currentTarget);
    setRefIndex(d3.bisectCenter(dates, x.invert(mx - MARGIN.left)));
  }

  if (width === 0) return null;

  const ruleX = x(dates[refIndex]);

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Index chart of seven technology stocks, 2013 to 2018, priced relative to a reference date that follows the pointer"
      style={{ touchAction: 'none' }}
      onPointerMove={handlePointerMove}
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        <line
          x1={0}
          x2={innerWidth}
          y1={y(1)}
          y2={y(1)}
          stroke="var(--muted)"
          strokeWidth={1}
        />
        <text x={-MARGIN.left} y={-8} fill="var(--muted)" fontSize={11}>
          {`↑ Price relative to ${d3.utcFormat('%b %-d, %Y')(dates[refIndex])}`}
        </text>
        <line
          x1={ruleX}
          x2={ruleX}
          y1={0}
          y2={innerHeight}
          stroke="var(--text)"
          strokeWidth={1}
          pointerEvents="none"
        />
        {paths.map((s) => (
          <g
            key={s.symbol}
            transform={`translate(0,${y(1) - y(s.values[refIndex])})`}
            pointerEvents="none"
          >
            <path
              d={s.d}
              fill="none"
              stroke={color(s.symbol)}
              strokeWidth={1.5}
              strokeLinejoin="round"
              strokeLinecap="round"
            />
            <text
              x={innerWidth + 4}
              y={y(s.last)}
              dy="0.32em"
              fill={color(s.symbol)}
              fontSize={10}
              fontWeight={600}
              paintOrder="stroke"
              stroke="var(--panel)"
              strokeWidth={3}
            >
              {s.symbol}
            </text>
          </g>
        ))}
      </g>
    </svg>
  );
}
